"""Tests for ledgerly.fx.convert."""
import datetime
import unittest

from decimal import Decimal

from ledgerly.money import Money

from ledgerly.fx.convert import (
    conversion_due_date,
    convert_conversion,
    convert_float,
    net_conversion,
    normalize_conversion_ref,
    quote_conversion,
    scaled_conversion,
    total_conversion,
)


class TestFxConvert(unittest.TestCase):
    def test_convert_conversion(self):
        self.assertEqual(convert_conversion(Money(Decimal("100.0"), "USD"), 'USD', 'EUR'), Money(Decimal("92.13"), "EUR"))

    def test_quote_conversion(self):
        self.assertEqual(quote_conversion(Money(Decimal("100.0"), "USD"), 'USD', 'EUR', 50), Money(Decimal("91.67"), "EUR"))

    def test_net_conversion(self):
        self.assertEqual(net_conversion(Money(Decimal("200.0"), "USD"), Decimal("10.0"), 'USD'), Money(Decimal("180.0"), "USD"))

    def test_scaled_conversion(self):
        self.assertEqual(scaled_conversion(Money(Decimal("10.0"), "USD"), Decimal("1.5"), 'USD'), Money(Decimal("15.0"), "USD"))

    def test_total_conversion(self):
        self.assertEqual(total_conversion([Money(Decimal("1.25"), "USD"), Money(Decimal("2.5"), "USD"), Money(Decimal("3.0"), "USD")], 'USD'), Money(Decimal("6.75"), "USD"))

    def test_convert_float(self):
        self.assertEqual(convert_float(100.0, 'USD', 'EUR'), 92.13)

    def test_normalize_conversion_ref(self):
        self.assertEqual(normalize_conversion_ref("  ab_12 cd "), "AB-12-CD")

    def test_conversion_due_date(self):
        self.assertEqual(conversion_due_date(datetime.date(2026, 10, 30), 1), datetime.date(2026, 11, 2))


if __name__ == "__main__":
    unittest.main()
