from pathlib import Path
import ast
import importlib
import inspect

from decimal import Decimal
from ledgerly.money import Money


def offsets(text):
    lines = text.splitlines(keepends=True)
    starts = []
    pos = 0
    for line in lines:
        starts.append(pos)
        pos += len(line)
    return lines, starts


def node_text(text, starts, node):
    return text[starts[node.lineno - 1] + node.col_offset:
                starts[node.end_lineno - 1] + node.end_col_offset]


def const_string(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    return None


def call_arg_for_param(call, sig, name):
    params = list(sig.parameters.values())
    for i, arg in enumerate(call.args):
        if i < len(params) and params[i].name == name:
            return arg
    for kw in call.keywords:
        if kw.arg == name:
            return kw.value
    return None


def money_currency(call, sig, func_name, param_name):
    src = call_arg_for_param(call, sig, "src")
    dst = call_arg_for_param(call, sig, "dst")
    currency = call_arg_for_param(call, sig, "currency")
    if param_name == "amount" and src is not None and func_name.startswith(("convert_", "quote_")):
        return const_string(src) or "USD"
    if currency is not None:
        return const_string(currency) or "USD"
    return "USD"


def result_currency(call, sig, func_name):
    dst = call_arg_for_param(call, sig, "dst")
    currency = call_arg_for_param(call, sig, "currency")
    if dst is not None and func_name.startswith(("convert_", "quote_")):
        return const_string(dst) or "USD"
    if currency is not None:
        return const_string(currency) or "USD"
    return "USD"


def money_literal(node, currency):
    return 'Money(Decimal("%s"), "%s")' % (node_text_global[0][node.lineno - 1][node.col_offset:node.end_col_offset], currency)


def list_of_money(node, currency):
    parts = []
    for elt in node.elts:
        parts.append('Money(Decimal("%s"), "%s")' % (
            node_text_global[0][elt.lineno - 1][elt.col_offset:elt.end_col_offset], currency))
    return "[" + ", ".join(parts) + "]"


for path in sorted(Path("tests").glob("test_*.py")):
    text = path.read_text(encoding="utf-8")
    text = text.replace(
        "import unittest\n",
        "import unittest\n\nfrom decimal import Decimal\n\nfrom ledgerly.money import Money\n",
        1,
    )
    tree = ast.parse(text)
    lines, starts = offsets(text)
    node_text_global[0] = lines if 'node_text_global' in globals() else None
    # Store lines for the helper above.
    globals()['node_text_global'] = (lines, starts)

    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module and node.module.startswith("ledgerly."):
            mod = importlib.import_module(node.module)
            for alias in node.names:
                imported[alias.asname or alias.name] = getattr(mod, alias.name)

    replacements = []

    def add_node(node, replacement):
        start = starts[node.lineno - 1] + node.col_offset
        end = starts[node.end_lineno - 1] + node.end_col_offset
        replacements.append((start, end, replacement))

    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if not (isinstance(node.func, ast.Attribute) and node.func.attr == "assertEqual"):
            continue
        if len(node.args) < 2 or not isinstance(node.args[0], ast.Call):
            continue
        call = node.args[0]
        if not isinstance(call.func, ast.Name) or call.func.id not in imported:
            continue
        func = imported[call.func.id]
        func_name = call.func.id
        try:
            sig = inspect.signature(func)
        except (TypeError, ValueError):
            continue
        params = list(sig.parameters.values())

        # Special money-carrying list shapes.
        if func_name == "ledger_csv":
            rows = call.args[0]
            currency = const_string(call.args[1]) if len(call.args) > 1 else "USD"
            parts = []
            for row in rows.elts:
                vals = []
                for i, elt in enumerate(row.elts):
                    if i == 2:
                        vals.append('Money(Decimal("%s"), "%s")' % (
                            node_text(text, starts, elt), currency))
                    else:
                        vals.append(node_text(text, starts, elt))
                parts.append("(" + ", ".join(vals) + ")")
            add_node(rows, "[" + ", ".join(parts) + "]")
        elif func_name == "invoice_json":
            rows = call.args[0]
            currency = const_string(call.args[1]) if len(call.args) > 1 else "USD"
            parts = []
            for row in rows.elts:
