        self.assertEqual(invoice_json([('A-1', Money(Decimal("10.0"), "USD")), ('B-2', Money(Decimal("2.5"), "USD"))], 'USD'), '{"currency":"USD","lines":[{"sku":"A-1","amount":10.0},{"sku":"B-2","amount":2.5}],"total":12.5}')

    def test_format_json(self):
        self.assertEqual(format_json(Money(Decimal("2.5"), "USD"), 'USD'), '2.50 USD')

    def test_total_json(self):
        self.assertEqual(total_json([Money(Decimal("1.25"), "USD"), Money(Decimal("2.5"), "USD"), Money(Decimal("3.0"), "USD")], 'USD'), Money(Decimal("6.75"), "USD"))

